package com.example.bikerental; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="app_notifications") public class AppNotification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String username; @Column(nullable=false,length=500) private String message; private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) private boolean readFlag=false; public AppNotification(){} public AppNotification(String u,String m){username=u;message=m;} public Long getId(){return id;} public String getUsername(){return username;} public String getMessage(){return message;} public LocalDateTime getCreatedAt(){return createdAt;} public boolean isReadFlag(){return readFlag;} public void setReadFlag(boolean v){readFlag=v;} }